<?php
require __DIR__.'/../app/bootstrap.php';
$me=require_login();if($me['role']!=='owner'){http_response_code(403);exit('Owner only.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(422);exit;} $s=$pdo->prepare('UPDATE staff_sessions SET revoked_at=NOW() WHERE id=? AND revoked_at IS NULL');$s->execute([$id]);audit($pdo,(int)$me['id'],'session.revoked',['session_id'=>$id]);header('Location: session-audit.php');exit;}
$rows=$pdo->query('SELECT s.id,s.ip_address,s.user_agent,s.started_at,s.last_seen_at,s.revoked_at,u.username FROM staff_sessions s JOIN users u ON u.id=s.user_id ORDER BY s.started_at DESC LIMIT 200')->fetchAll();
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff session audit</title><link rel="stylesheet" href="style.css"><main><a href="dashboard.php">← Dashboard</a><h1>Staff sessions</h1><p>Private security records. Protect IP addresses and delete them when no longer needed.</p><section class="panel"><div class="tablewrap"><table><tr><th>User</th><th>IP address</th><th>Device</th><th>Start</th><th>Last seen</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['username'])?></td><td><?=h($r['ip_address'])?></td><td><?=h($r['user_agent'])?></td><td><?=h($r['started_at'])?></td><td><?=h($r['last_seen_at'])?></td><td><?=$r['revoked_at']?'Revoked':'Active'?></td><td><?php if(!$r['revoked_at']):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="muted">Revoke</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section></main></html>